'use strict';
// Playback only. Inference, optimization and plant integration are recorded in Python.
(async function implicitReview(){
  const container=document.getElementById('implicit-comparisons');if(!container)return;
  const dir='data/implicit-monitoring-300',cache=new Map();
  async function read(name){if(cache.has(name))return cache.get(name);const job=(async()=>{const r=await fetch(`${dir}/${name}`);if(!r.ok)throw Error(`${name}: HTTP ${r.status}`);if(!name.endsWith('.gz'))return r.json();const bytes=new Uint8Array(await r.arrayBuffer());return bytes[0]===31?new Response(new Blob([bytes]).stream().pipeThrough(new DecompressionStream('gzip'))).json():JSON.parse(new TextDecoder().decode(bytes));})();cache.set(name,job);return job;}
  const colors=['#086c7c','#b65a26'],names=['Disturbance-aware MBD','MBD + execution RPCBF'];
  const ramps={warm:['#fff7ec','#fee8c8','#fdbb84','#fc8d59','#d7301f','#7f0000'],blue:['#f7fbff','#deebf7','#9ecae1','#4292c6','#2171b5','#08306b'],teal:['#f7fcfd','#d9f0e9','#92d2c8','#41aeab','#137e7d','#06484c']};
  const rgb=h=>[1,3,5].map(i=>parseInt(h.slice(i,i+2),16));Object.keys(ramps).forEach(k=>ramps[k]=ramps[k].map(rgb));
  const layers={clarity:{label:'Clarity q',max:1,unit:'higher clarity',ramp:'warm'},deficit:{label:'Deficit below target',max:.7,unit:'larger deficit',ramp:'warm'},mean:{label:'Learned mean wind speed',max:8,unit:'m/s',ramp:'teal'},std:{label:'Full POAM uncertainty σ',max:1.8,unit:'m/s · used by safety',ramp:'blue'},planning_std:{label:'Performance sampling σ',max:1.8,unit:'m/s · prior spread suppressed',ramp:'blue'},support:{label:'Measurement support r',max:1,unit:'fractional variance reduction',ramp:'teal'}};
  function shade(v,l){const a=ramps[l.ramp],z=Math.max(0,Math.min(1,v/l.max))*(a.length-1),i=Math.min(a.length-2,Math.floor(z)),f=z-i;return a[i].map((x,k)=>Math.round(x+(a[i+1][k]-x)*f));}
  function at(rows,t,key=r=>r.t){let a=0,b=rows.length-1;while(b-a>1){const c=(a+b)>>1;if(key(rows[c])<=t)a=c;else b=c;}return key(rows[b])<=t?b:a;}
  function sample(rows,t){const i=at(rows,t,r=>r[0]),a=rows[i],b=rows[Math.min(i+1,rows.length-1)],f=b[0]>a[0]?(t-a[0])/(b[0]-a[0]):0;return a.map((v,k)=>[11,18].includes(k)?v:v+f*(b[k]-v));}
  try{
    const [manifest,env]=await Promise.all([read('manifest.json'),read('environment.json')]);
    const [nx,ny]=env.grid,H=env.bounds[1][1]*100,W=env.bounds[1][0]*100;
    const xy=p=>[p[0]*100,H-p[1]*100],line=points=>points.map(p=>xy(p).map(v=>v.toFixed(1)).join(',')).join(' ');
    const mean=(a)=>a.reduce((s,x)=>s+x,0)/a.length;
    const freeSet=new Set(env.free_indices),freeIndex=new Map(env.free_indices.map((k,n)=>[k,n]));
    container.innerHTML='';
    for(const scenario of [1,2]){
      const root=document.createElement('section');root.className='implicit-comparison';root.id=`implicit-scenario-${scenario}`;root.dataset.implicitScenario=scenario;
      root.innerHTML=`<div class="implicit-heading"><h3>Scenario ${scenario} · unknown wind · 300 s</h3><span class="implicit-badge">No initial survey</span></div><div class="implicit-options"><label>Map layer <select data-control="layer" aria-label="Unknown wind scenario ${scenario} map layer">${Object.entries(layers).map(([v,l])=>`<option value="${v}">${l.label}</option>`).join('')}</select></label><label><input type="checkbox" data-control="vectors" checked> Learned wind vectors</label><label><input type="checkbox" data-control="forecast"> Two predicted trajectories</label><label><input type="checkbox" data-control="seeds"> Geometric paths</label></div><p class="implicit-status" role="status">Loading recordings…</p><div class="implicit-legend"><strong></strong><span>0</span><i class="implicit-scale"></i><span class="implicit-max"></span></div><div class="implicit-pair"><div class="implicit-transport" aria-label="Unknown wind scenario ${scenario} playback"><button type="button" data-action="play" disabled aria-pressed="false">▶ Play comparison</button><button type="button" data-action="restart" disabled>↺ Restart</button><label class="implicit-timeline"><input data-control="time" aria-label="Unknown wind scenario ${scenario} time" type="range" min="0" max="300" step="0.05" value="0" disabled></label><output>0.0 / 300.0 s</output><label>Jump <select data-control="jump"><option value="0">Start</option><option value="30">30 s</option><option value="150">150 s</option><option value="300">End · 300 s</option></select></label><label>Speed <select data-control="speed"><option>1</option><option>2</option><option selected>4</option><option>8</option><option>16</option></select>×</label></div></div><p class="implicit-hover">Move over either map to inspect a recorded cell. Wind belief is displayed at the most recent saved posterior (5 s spacing).</p>`;
      container.append(root);const find=s=>root.querySelector(s),pair=find('.implicit-pair');let time=0,playing=false,last=null;
      const metadata=['aware','baseline'].map(m=>manifest.runs.find(r=>r.scenario===scenario&&r.method===m));
      const records=await Promise.all(metadata.map(r=>read(r.file)));
      function play(value){playing=value;find('[data-action=play]').textContent=value?'Ⅱ Pause':'▶ Play comparison';find('[data-action=play]').setAttribute('aria-pressed',String(value));}
      const panels=records.map((record,i)=>{
        const clip=`implicit-clip-${scenario}-${i}`,arrow=`implicit-arrow-${scenario}-${i}`;
        const regions=env.regions.map(r=>{const [a,b]=r.bounds;return `<rect x="${a[0]*100}" y="${H-b[1]*100}" width="${(b[0]-a[0])*100}" height="${(b[1]-a[1])*100}" fill="none" stroke="${r.label==='A'?'#2563eb':'#b45309'}" stroke-width="2"/><text class="region-label" x="${a[0]*100+13}" y="${H-b[1]*100+25}">Region ${r.label}</text>`;}).join('');
        const obstacles=env.obstacles.map(o=>`<circle cx="${o[0]*100}" cy="${H-o[1]*100}" r="${o[2]*100}" fill="#75858c"/>`).join('');
        const card=document.createElement('article');card.className='implicit-card';
        card.innerHTML=`<header><h4>${names[i]}</h4><p>${i===0?'Measured belief + relaxed RPCBF in planning':'Still-air planning; shared uncertain execution filter'}</p></header><div class="implicit-map"><svg viewBox="-4 -4 ${W+8} ${H+8}" role="img" aria-label="Unknown wind scenario ${scenario}: ${names[i]}"><defs><clipPath id="${clip}"><rect width="${W}" height="${H}"/></clipPath><marker id="${arrow}" viewBox="0 0 8 8" refX="7" refY="4" markerWidth="4" markerHeight="4" orient="auto-start-reverse"><path d="M0 0L8 4L0 8Z" fill="#123f60"/></marker></defs><rect width="${W}" height="${H}" fill="#fff7ec"/><image class="implicit-heat" width="${W}" height="${H}"/>${regions}${obstacles}<g clip-path="url(#${clip})"><g class="implicit-vectors" opacity=".7"></g><g class="implicit-seeds"></g><g class="implicit-forecast"></g><polyline class="implicit-halo" fill="none" stroke="white" stroke-width="6"/><polyline class="implicit-trace" fill="none" stroke="${colors[i]}" stroke-width="3"/><circle class="implicit-dot" r="6" fill="${colors[i]}" stroke="white" stroke-width="2"/></g><rect width="${W}" height="${H}" fill="none" stroke="#889eaa"/></svg></div><p class="implicit-live"></p>`;
        const details=document.createElement('div');details.className='implicit-details';const s=record.summary;
        details.innerHTML=`<div class="implicit-metrics"><div><span>Clarity A</span><b data-metric="a"></b></div><div><span>Clarity B</span><b data-metric="b"></b></div><div><span>Mean deficit</span><b data-metric="deficit"></b></div><div><span>Accumulated deficit</span><b data-metric="cost"></b></div></div><p><strong>300 s: ${s.contact?'contact recorded':'no contact'} · A not reached</strong><br>Minimum clearance ${s.min_clearance_m.toFixed(3)} m · ${s.infeasible_execution_steps} infeasible filter steps / 6000.</p><p class="implicit-belief-summary"></p><details><summary>Current plan and runtime</summary><div class="implicit-decision"></div></details><div class="implicit-chart"></div>`;
        const rows=record.samples.filter((_,n)=>n%10===0),pts=k=>rows.map(s=>`${30+s[0]/300*530},${115-s[k]*95}`).join(' ');
        details.querySelector('.implicit-chart').innerHTML=`<p><span style="color:#2563eb">━ Region A</span> &nbsp; <span style="color:#b45309">━ Region B</span> · clarity; dashed target 0.70</p><svg viewBox="0 0 585 145" role="img" aria-label="Recorded regional clarity over 300 seconds"><path d="M30 20V115H560" stroke="#9aaeba" fill="none"/><path d="M30 48.5H560" stroke="#8397a6" stroke-dasharray="4 4"/><polyline points="${pts(15)}" fill="none" stroke="#2563eb" stroke-width="1.8"/><polyline points="${pts(16)}" fill="none" stroke="#b45309" stroke-width="1.8"/><line class="implicit-chart-time" y1="20" y2="115" stroke="#173247"/><text x="10" y="24">1</text><text x="10" y="119">0</text><text x="28" y="136">0 s</text><text x="525" y="136">300 s</text></svg>`;
        const p={record,card,details,arrow,heatKey:'',beliefKey:-1,planKey:-1};
        card.querySelector('svg').addEventListener('pointermove',e=>{const svg=e.currentTarget,point=new DOMPoint(e.clientX,e.clientY).matrixTransform(svg.getScreenCTM().inverse()),x=point.x/100,y=(H-point.y)/100,ix=Math.floor(x/env.dx_m),iy=Math.floor(y/env.dx_m),cell=iy*nx+ix;if(ix<0||ix>=nx||iy<0||iy>=ny||!freeSet.has(cell)){find('.implicit-hover').textContent='Obstacle or outside the environment.';return;}const b=record.belief_frames[at(record.belief_frames,time)],q=record.clarity_frames[at(record.clarity_frames,time)].q[freeIndex.get(cell)],w=b.mean[cell];find('.implicit-hover').textContent=`${names[i]} · (${x.toFixed(2)}, ${y.toFixed(2)}) m · clarity ${q.toFixed(3)} · mean wind (${w[0].toFixed(2)}, ${w[1].toFixed(2)}) m/s · full σ ${b.std[cell].toFixed(2)} m/s · performance σ ${b.planning_std[cell].toFixed(2)} m/s · belief at ${b.t} s`;});return p;
      });
      pair.prepend(...panels.map(p=>p.card));pair.append(...panels.map(p=>p.details));
      function draw(){
        const layer=find('[data-control=layer]').value,l=layers[layer];
        find('.implicit-legend strong').textContent=l.label;find('.implicit-max').textContent=`${l.max.toFixed(l.max===1?0:1)} ${l.unit}`;find('.implicit-scale').style.background=`linear-gradient(90deg,${ramps[l.ramp].map(c=>`rgb(${c})`).join(',')})`;
        for(const p of panels){const r=p.record,s=sample(r.samples,time),pos=xy(s.slice(1,3)),bi=at(r.belief_frames,time),b=r.belief_frames[bi],qi=at(r.clarity_frames,time),q=r.clarity_frames[qi].q,key=layer+(layer==='clarity'||layer==='deficit'?qi:bi);
          const trace=line([...r.samples.filter((v,n)=>n%5===0&&v[0]<time).map(v=>v.slice(1,3)),s.slice(1,3)]);for(const cls of ['implicit-trace','implicit-halo'])p.card.querySelector('.'+cls).setAttribute('points',trace);const dot=p.card.querySelector('.implicit-dot');dot.setAttribute('cx',pos[0]);dot.setAttribute('cy',pos[1]);
          if(key!==p.heatKey){p.heatKey=key;const c=document.createElement('canvas');c.width=nx;c.height=ny;const ctx=c.getContext('2d'),pix=ctx.createImageData(nx,ny);env.free_indices.forEach((cell,n)=>{let v;if(layer==='clarity')v=q[n];else if(layer==='deficit')v=Math.max(0,env.targets[n]-q[n]);else if(layer==='mean')v=Math.hypot(...b.mean[cell]);else v=b[layer][cell];const rgb=shade(v,l),off=((ny-1-Math.floor(cell/nx))*nx+cell%nx)*4;rgb.forEach((x,k)=>pix.data[off+k]=x);pix.data[off+3]=255;});ctx.putImageData(pix,0,0);p.card.querySelector('.implicit-heat').setAttribute('href',c.toDataURL());}
          if(bi!==p.beliefKey){p.beliefKey=bi;let arrows='';for(let y=2;y<ny;y+=4)for(let x=2;x<nx;x+=4){const cell=y*nx+x;if(!freeSet.has(cell))continue;const w=b.mean[cell],mag=Math.hypot(...w);if(mag<.06)continue;const p0=xy([(x+.5)*env.dx_m,(y+.5)*env.dx_m]),scale=4;arrows+=`<path d="M${p0[0]} ${p0[1]}l${w[0]*scale} ${-w[1]*scale}" stroke="#123f60" stroke-width="1.8" marker-end="url(#${p.arrow})"/>`;}p.card.querySelector('.implicit-vectors').innerHTML=arrows;const sigma=mean(env.free_indices.map(k=>b.std[k])),perf=mean(env.free_indices.map(k=>b.planning_std[k]));p.details.querySelector('.implicit-belief-summary').textContent=`Belief at ${b.t} s · ${b.observations} actual measurements · mean full σ ${sigma.toFixed(3)} m/s · mean performance σ ${perf.toFixed(3)} m/s. Wind uncertainty remains high away from supported observations.`;}
          p.card.querySelector('.implicit-vectors').style.display=find('[data-control=vectors]').checked?'':'none';
          p.card.querySelector('.implicit-live').textContent=`Belief at ${b.t} s · ${b.observations} samples · speed ${Math.hypot(s[3],s[4]).toFixed(2)} m/s · clearance ${s[12].toFixed(3)} m`;
          for(const [k,v]of Object.entries({a:s[15],b:s[16],deficit:s[13],cost:s[14]}))p.details.querySelector(`[data-metric=${k}]`).textContent=v.toFixed(3);
          const pi=at(r.plans,time),plan=r.plans[pi];if(pi!==p.planKey){p.planKey=pi;p.card.querySelector('.implicit-forecast').innerHTML=plan.predicted_states.map((xs,i)=>`<polyline points="${line(xs.map(x=>x.slice(0,2)))}" fill="none" stroke="${i?'#be185d':'#5b21b6'}" stroke-width="2" stroke-dasharray="${i?'2 5':'7 4'}"/>`).join('');p.card.querySelector('.implicit-seeds').innerHTML=plan.initialization.coarse_paths.map(path=>`<polyline points="${line(path)}" fill="none" stroke="#64748b" stroke-width="1.5" stroke-dasharray="4 5"/>`).join('');const t=plan.timing;p.details.querySelector('.implicit-decision').innerHTML=`Plan at ${plan.t} s · ${plan.observations} observations · 15 s horizon.<br>Total ${plan.wall_seconds.toFixed(3)} s${t.compilation_included?' (includes compilation)':''}. Geometry ${(t.initialization*1000).toFixed(1)} ms; fields ${(t.field_sampling*1000).toFixed(1)} ms; MBD + forecasts ${(t.optimization_validation*1000).toFixed(1)} ms; posterior ${(t.actual_posterior_update*1000).toFixed(1)} ms.<br>Expected cost ${plan.expected_cost.toFixed(3)} · ${plan.predicted_contacts.filter(Boolean).length}/2 forecast contacts · ${plan.selected_origin}.<br>Performance field maximum component ${plan.planning_field_max_abs.toFixed(2)} m/s; full uncertainty maximum ${plan.safety_prior_std_max.toFixed(2)} m/s.`;}
          p.card.querySelector('.implicit-forecast').style.display=find('[data-control=forecast]').checked?'':'none';p.card.querySelector('.implicit-seeds').style.display=find('[data-control=seeds]').checked?'':'none';const cursor=p.details.querySelector('.implicit-chart-time');cursor.setAttribute('x1',30+time/300*530);cursor.setAttribute('x2',30+time/300*530);
        }
        find('[data-control=time]').value=time;find('output').textContent=`${time.toFixed(1)} / 300.0 s`;
      }
      find('[data-action=play]').addEventListener('click',()=>{if(time>=300)time=0;play(!playing);draw();});find('[data-action=restart]').addEventListener('click',()=>{time=0;play(true);draw();});find('[data-control=time]').addEventListener('input',e=>{time=+e.target.value;play(false);draw();});find('[data-control=jump]').addEventListener('change',e=>{time=+e.target.value;play(false);draw();});for(const name of ['layer','vectors','forecast','seeds'])find(`[data-control=${name}]`).addEventListener('change',draw);root.querySelectorAll('button,input').forEach(x=>x.disabled=false);
      find('.implicit-status').textContent=metadata.map((r,i)=>`${names[i]}: ${(1000*r.timing.total.median_s).toFixed(0)} ms median / ${(1000*r.timing.total.max_s).toFixed(0)} ms max warm planning`).join(' · ')+'.';draw();
      function tick(now){const dt=last===null?0:Math.min(.15,(now-last)/1000);last=now;if(playing&&!document.hidden){time=Math.min(300,time+dt*+find('[data-control=speed]').value);draw();if(time>=300)play(false);}requestAnimationFrame(tick);}requestAnimationFrame(tick);
    }
    const cols=[['initialization','Geometric starts'],['field_sampling','Two planning + two safety fields'],['actual_posterior_update','Latest actual POAM update'],['optimization_validation','MBD + selected forecasts'],['total','Total warm planning']];
    const aware=manifest.runs.filter(r=>r.method==='aware');document.getElementById('implicit-runtime-table').innerHTML=`<table><thead><tr><th>Module · median</th><th>Scenario 1</th><th>Scenario 2</th></tr></thead><tbody>${cols.map(([k,n])=>`<tr><td>${n}</td>${aware.map(r=>`<td>${(r.timing[k].median_s*1000).toFixed(1)} ms</td>`).join('')}</tr>`).join('')}<tr><td>Total · maximum</td>${aware.map(r=>`<td>${(r.timing.total.max_s*1000).toFixed(1)} ms</td>`).join('')}</tr></tbody></table>`;
    document.querySelectorAll('#implicit-review [data-tex]').forEach(el=>{if(window.katex)window.katex.render(el.dataset.tex,el,{throwOnError:false,displayMode:true});else el.textContent=el.dataset.tex;});
  }catch(error){container.innerHTML=`<p role="alert">The new recordings could not load: ${error.message}. Existing demonstrations above are independent.</p>`;console.error(error);}
})();
